import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import { webcrypto } from 'node:crypto';
import tmdbProxy, { CinemaRateLimiter } from './tmdb-proxy/worker.mjs';

const i18nKeys = ['workspaceEyebrow', 'workspaceTitle', 'tabSession', 'tabCollection', 'tabHistory', 'filmsNoun', 'findMovies', 'eyebrow', 'headline1', 'headline2', 'intro', 'wheelCaption', 'spin', 'collectionEyebrow', 'collectionTitle', 'collectionSummary', 'editMovies', 'editorHelp', 'moviesLabel', 'reset', 'finishEdit', 'filterTitle', 'surpriseTitle', 'metadataTitle', 'sharingTitle', 'portabilityTitle', 'historyEyebrow', 'clearHistory', 'historyNote', 'footerLeft', 'footerRight'];

async function createApp(seed = {}, options = {}) {
  const nodes = new Map();
  const downloads = [];
  const downloadNames = [];
  const clipboardWrites = [];
  function makeElement(selector) {
    const classes = new Set();
    const value = selector.match(/#(?:filter|metadata)-mood-(light|scary|nostalgic)$/)?.[1] ?? (selector === '#marathon-count' ? '3' : selector === '#draw-mode' ? 'wheel' : selector === '#draw-pace' ? 'fast' : '');
    const options = ['#theme', '#portability-theme'].includes(selector) ? [{ textContent: '', value: 'halloween' }, { textContent: '', value: 'christmas' }] : selector === '#draw-mode' ? ['wheel', 'doors', 'shuffle', 'posters'].map(value => ({ value, textContent: '' })) : selector === '#draw-pace' ? ['fast', 'suspense'].map(value => ({ value, textContent: '' })) : selector === '#playlist-import-mode' ? [{ textContent: '', value: 'merge' }, { textContent: '', value: 'replace' }] : selector === '#filter-duration' ? ['any', '90', '120', '150', '180'].map(value => ({ value, textContent: '' })) : [];
    const element = { selector, value, textContent: '', innerHTML: '', disabled: false, checked: false, hidden: false, children: [], attributes: {}, listeners: {}, style: {}, dataset: {}, options, files: [], classList: { add(...names) { names.forEach(name => classes.add(name)); }, remove(...names) { names.forEach(name => classes.delete(name)); }, toggle(name, force) { if (force ?? !classes.has(name)) classes.add(name); else classes.delete(name); }, contains: name => classes.has(name) }, addEventListener(type, fn) { this.listeners[type] = fn; }, dispatch(type) { return this.listeners[type]?.({ target: this, preventDefault() {} }); }, setAttribute(name, value) { this.attributes[name] = value; }, getAttribute(name) { return this.attributes[name] ?? null; }, removeAttribute(name) { delete this.attributes[name]; }, replaceChildren(...items) { this.children = items; if (this.selector.startsWith('select') || ['#surprise-mood', '#surprise-duration', '#metadata-movie'].includes(this.selector)) this.options = []; }, append(...items) { this.children.push(...items); if (this.selector.startsWith('select') || ['#surprise-mood', '#surprise-duration', '#metadata-movie'].includes(this.selector)) this.options.push(...items); }, querySelector(query) { const value = query.match(/\[value="([^"]+)"\]/)?.[1]; return this.options.find(option => option.value === value) ?? null; }, focus() { this.focused = true; }, click() { this.clicked = true; if (this.download) downloadNames.push(this.download); }, remove() { this.removed = true; } };
    element.firstElementChild = { style: {} };
    return element;
  }
  function node(selector) {
    if (!nodes.has(selector)) nodes.set(selector, makeElement(selector));
    return nodes.get(selector);
  }
  const canvasContext = { createRadialGradient() { return { addColorStop() {} }; }, clearRect() {}, save() {}, restore() {}, translate() {}, rotate() {}, beginPath() {}, moveTo() {}, arc() {}, closePath() {}, fill() {}, stroke() {}, fillText() {}, measureText: text => ({ width: text.length * 14 }) };
  node('#wheel').getContext = () => canvasContext;
  const storage = new Map(Object.entries(seed).map(([key, value]) => [key, JSON.stringify(value)]));
  const requests = [];
  const fetchImplementation = options.fetch ?? (async () => { throw new TypeError('offline'); });
  const fetchMock = async (url, requestOptions) => { requests.push({ url: String(url), requestOptions }); return fetchImplementation(url, requestOptions); };
  const windowObject = options.window ?? {};
  const audios = [];
  const animationFrames = [];
  let now = 0;
  let reduceMotion = false;
  let confirmDecision = false;
  let confirmMessage = '';
  class InstrumentedURL extends URL {
    static createObjectURL(blob) { downloads.push(blob); return `blob:test-${downloads.length}`; }
    static revokeObjectURL() {}
  }
  const urlImplementation = options.URL ?? InstrumentedURL;
  const sandbox = vm.createContext({ document: { querySelector: node, querySelectorAll: selector => selector === '[data-i18n]' ? i18nKeys.map(key => { const element = node(`i18n:${key}`); element.setAttribute('data-i18n', key); return element; }) : selector === '[data-collection]' ? ['all', 'halloween-family', 'horror', 'christmas-classics', 'christmas-family'].map(key => { const element = node(`collection:${key}`); element.setAttribute('data-collection', key); return element; }) : selector === '.mystery-door' ? node('#doors').children : [], documentElement: {}, body: node('body'), createElement: tag => makeElement(tag), fonts: null }, localStorage: { getItem: key => storage.get(key) ?? null, setItem: (key, value) => storage.set(key, value) }, Audio: class { constructor(src) { this.src = src; this.paused = true; this.playCount = 0; audios.push(this); } play() { this.paused = false; this.playCount++; return Promise.resolve(); } pause() { this.paused = true; } }, crypto: webcrypto, matchMedia: () => ({ matches: reduceMotion }), performance: { now: () => now }, requestAnimationFrame: fn => animationFrames.push(fn), confirm: message => { confirmMessage = message; return confirmDecision; }, URL: urlImplementation, AbortController, TextEncoder, TextDecoder, Uint8Array, btoa: value => Buffer.from(value, 'binary').toString('base64'), atob: value => Buffer.from(value, 'base64').toString('binary'), Blob, setTimeout, navigator: options.navigator ?? { clipboard: { writeText: async text => clipboardWrites.push(text) } }, location: options.location ?? { href: 'https://joaopef.github.io/halloween-roulette/' }, window: windowObject, fetch: fetchMock });
  vm.runInContext(await readFile('movies.js', 'utf8'), sandbox);
  vm.runInContext(await readFile('catalog.js', 'utf8'), sandbox);
  vm.runInContext(await readFile('app.js', 'utf8'), sandbox);
  return { node, storage, audios, animationFrames, sandbox, requests, downloads, downloadNames, clipboardWrites, setNow: value => { now = value; }, setReduceMotion: value => { reduceMotion = value; }, setConfirm: value => { confirmDecision = value; }, confirmMessage: () => confirmMessage };
}

const app = await createApp();
const { node, storage, audios, animationFrames, sandbox } = app;
const evaluate = expression => vm.runInContext(expression, sandbox);
assert.equal(node('#count').textContent, 19);
assert.equal(node('#eligibility-summary').hidden, true, 'do not repeat the total when every movie is eligible');
assert.equal(node('#movie-editor').hidden, true);
assert.equal(node('#edit-toggle').getAttribute('aria-expanded'), 'false');
assert.equal(node('#sound').getAttribute('aria-pressed'), 'true');
assert.equal(node('#sound').getAttribute('aria-label'), 'Desativar som');
assert.equal(node('#theme').value, 'halloween');
assert.equal(node('#catalog-results').children.length, 8, 'Halloween suggestions omit the 19 movies already on the wheel');
assert.equal(evaluate('CURATED_CATALOG.halloween.every(movie => safePosterUrl(movie.posterUrl))'), true, 'every curated Halloween film has a verified poster');
assert.equal(evaluate('playlistRecords().every(movie => safePosterUrl(movie.posterUrl))'), true, 'all 19 starter titles receive posters without changing their identity');
assert.match(node('#catalog-status').textContent, /TMDB não está ativa/);
assert.equal(node('#tmdb-attribution').hidden, true, 'inactive TMDB does not claim an active integration');
assert.equal(node('#history-stats').textContent, '17 filmes diferentes · 24 sorteios');
assert.equal(node('#history').children.length, 5);
assert.equal(evaluate("playlistRecords().find(movie => movie.title === 'Beetlejuice (1988)').runtimeMinutes"), 92, 'exact starter matches receive curated runtime metadata');
assert.equal(evaluate("playlistRecords().find(movie => movie.title === 'Beetlejuice (1988)').moods.includes('light')"), true);
assert.equal(audios.every(audio => audio.playCount === 0), true, 'page load must not autoplay');

node('#history-toggle').dispatch('click');
assert.equal(node('#history').children.length, 17);
assert.equal(node('#history-toggle').textContent, 'Mostrar menos');
node('#history-toggle').dispatch('click');
assert.equal(node('#history').children.length, 5);

node('#language').value = 'en'; node('#language').dispatch('change');
assert.equal(sandbox.document.documentElement.lang, 'en');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).language, 'en', 'language preference persists');
assert.equal(node('i18n:collectionTitle').textContent, 'Movies on the wheel');
assert.equal(node('#history-stats').textContent, '17 unique movies · 24 draws');
assert.equal(node('#history').children.length, 5, 'language switch preserves wall of fame view');
assert.equal(node('#theme').value, 'halloween');

node('#edit-toggle').dispatch('click');
assert.equal(node('#movie-editor').hidden, false);
node('#movies').value = 'Only one\nOnly one\n'; node('#movies').dispatch('input');
assert.equal(node('#count').textContent, 1); assert.equal(node('#eligible-count').textContent, 1); assert.equal(node('#spin').disabled, false);
const singleSpin = evaluate('spin()'); app.setNow(5000); animationFrames.shift()(5000);
assert.equal((await singleSpin).movie, 'Only one', 'a single eligible movie can be drawn');
assert.equal(node('#history-stats').textContent, '18 unique movies · 25 draws');
node('#movies').value = 'A\nB'; node('#movies').dispatch('input');
assert.equal(evaluate('movieList().length'), 2, 'duplicates are removed');
const originalMovies = node('#movies').value;
node('#reset').dispatch('click');
assert.equal(node('#count').textContent, 19, 'reset restores the original selection');
node('#movies').value = originalMovies; node('#movies').dispatch('input');
node('#finish-edit').dispatch('click');
assert.equal(node('#movie-editor').hidden, true);

node('#sound').dispatch('click');
assert.equal(node('#sound').getAttribute('aria-pressed'), 'false');
assert.equal(node('#sound').getAttribute('aria-label'), 'Turn sound on');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).soundEnabled, false);
node('#sound').dispatch('click');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).soundEnabled, true);
const pendingSpin = node('#spin').dispatch('click');
assert.equal(evaluate('spin({type: "click"})'), undefined, 'an event is not a movie pool');
const audioStarts = audios[0].playCount;
node('#spin').dispatch('click');
assert.equal(audios[0].playCount, audioStarts, 'repeated clicks cannot restart audio or create another draw');
assert.equal(animationFrames.length, 1);
assert.equal(audios[0].paused, false, 'roll sound starts during spin when enabled');
assert.equal(node('#movies').disabled, true); assert.equal(node('#reset').disabled, true);
node('#sound').dispatch('click');
assert.equal(audios.every(audio => audio.paused), true, 'disabling sound silences all audio immediately');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).soundEnabled, false);
node('#sound').dispatch('click');
assert.equal(audios[0].paused, false, 'reenabling sound resumes the wheel while spinning');
assert.equal(node('#theme').disabled, true, 'theme cannot change in the middle of a spin');
app.setNow(10000); animationFrames.shift()(10000);
const result = await pendingSpin;
assert.equal(audios[1].playCount, 2, 'one ending chime per completed draw, including the preceding single-film draw');
assert.ok(['A', 'B'].includes(result.movie));
assert.equal(node('#result-title').textContent, result.movie);
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).themes.halloween.sessions.length, 2, 'each standard spin is recorded as a one-film session');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).themes.halloween.sessions.at(-1).movies[0].id, result.id);
const titleBeforeLanguageChange = node('#result-title').textContent;
node('#language').value = 'pt-PT'; node('#language').dispatch('change');
assert.equal(node('#result-title').textContent, titleBeforeLanguageChange, 'language switch preserves selected movie');
assert.equal(node('#result-description').textContent, 'Apaga as luzes e carrega no play. Boa sessão!', 'language switch translates result instructions without changing the movie');
assert.equal(node('#result-label').textContent, 'O FILME DESTA NOITE', 'the completed result label follows the active language');
assert.equal(node('#hint').textContent, 'O destino escolheu. Agora só faltam as pipocas.');
assert.equal(node('#history-title').textContent, 'Mural da Fama');
assert.equal(node('#result').classList.contains('winner'), true);
assert.equal(node('#movies').disabled, false); assert.equal(node('#reset').disabled, false);
assert.equal(audios[0].paused, true);
assert.equal(audios[1].paused, false, 'ending chime plays after the spin when enabled');
const selectedByPointer = evaluate('Math.floor(((Math.PI * 2 - rotation) % (Math.PI * 2)) / (Math.PI * 2 / movieList().length))');
assert.equal(['A', 'B'][selectedByPointer], result.movie);
assert.equal(evaluate('winningIndex'), selectedByPointer, 'highlighted slice matches pointer and announcement');
const historyBeforeViewed = JSON.stringify(JSON.parse(storage.get('cinema-roulette-v5')).themes.halloween.history);
node('#watch-toggle').dispatch('click');
assert.equal(node('#watch-toggle').textContent, 'Desmarcar como visto');
const savedAfterViewed = JSON.parse(storage.get('cinema-roulette-v5'));
assert.equal(savedAfterViewed.themes.halloween.viewed.includes(result.id), true);
assert.equal(JSON.stringify(savedAfterViewed.themes.halloween.history), historyBeforeViewed, 'marking watched does not change draw history');
node('#watch-toggle').dispatch('click');
assert.equal(node('#watch-toggle').textContent, 'Marcar como visto', 'watched status can be undone');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).themes.halloween.viewed.includes(result.id), false);
node('#watch-toggle').dispatch('click');
node('#avoid-viewed').checked = true; node('#avoid-viewed').dispatch('change');
assert.equal(node('#eligible-count').textContent, 1, 'the watched result is excluded from the eligible count');
assert.equal(node('#spin').disabled, false, 'one unwatched movie is still enough to spin');
const remainingSpin = evaluate('spin()'); app.setNow(15000); animationFrames.shift()(15000);
const remainingResult = await remainingSpin;
assert.notEqual(remainingResult.id, result.id, 'avoiding watched movies excludes the watched result');
node('#watch-toggle').dispatch('click');
assert.equal(node('#eligible-count').textContent, 0, 'all watched movies exhaust the opt-in pool');
assert.equal(node('#spin').disabled, true);
assert.equal(node('#exhausted-actions').hidden, false);
node('#include-viewed').dispatch('click');
assert.equal(node('#eligible-count').textContent, 2, 'including watched movies restores the full pool');
node('#avoid-viewed').checked = true; node('#avoid-viewed').dispatch('change');
node('#reset-viewed').dispatch('click');
assert.equal(node('#eligible-count').textContent, 2, 'reset watched list leaves the playlist intact');
assert.equal(JSON.stringify(JSON.parse(storage.get('cinema-roulette-v5')).themes.halloween.history) === historyBeforeViewed, false, 'only actual spins add to history');

node('#sound').dispatch('click');
assert.equal(audios.every(audio => audio.paused), true, 'turning sound off after the spin silences the chime');
node('#movies').value = Array.from({ length: 61 }, (_, i) => `Film ${i}`).join('\n'); node('#movies').dispatch('input');
assert.equal(node('#spin').disabled, true); assert.match(node('#list-status').textContent, /60/);
node('#movies').value = Array.from({ length: 60 }, (_, i) => `Film ${i}`).join('\n'); node('#movies').dispatch('input');
assert.equal(node('#spin').disabled, false);

// Theme state stays independent, including the curated Christmas starter list.
node('#theme').value = 'christmas'; node('#theme').dispatch('change');
assert.equal(node('#count').textContent, 13);
assert.equal(node('#history-stats').textContent, '0 filmes diferentes · 0 sorteios');
assert.equal(node('body').dataset.theme, 'christmas');
assert.equal(node('#brand-name').innerHTML, 'CHRISTMAS <b>ROULETTE</b>');
assert.equal(node('#wheel-theme-label').textContent, 'NATAL', 'Christmas wheel label is localized');
assert.equal(node('#movies').value.includes('Klaus (2019)'), true);
assert.equal(node('#catalog-results').children.length, 9, 'Christmas suggestions omit movies already on the wheel');
node('#catalog-search').value = 'Home Alone'; node('#catalog-search').dispatch('input');
assert.equal(node('#catalog-results').children.length, 2, 'offline title search distinguishes the two Home Alone films');
node('#catalog-search').value = 'Home Alone 1990'; node('#catalog-search').dispatch('input');
assert.equal(node('#catalog-results').children.length, 1, 'year in search narrows remake results');
const homeAloneCard = node('#catalog-results').children[0];
const homeAloneActions = homeAloneCard.children[1].children.at(-1);
assert.equal(homeAloneActions.children[0].disabled, true, 'films already in the playlist cannot be added twice');
node('#catalog-search').value = 'unlisted title'; node('#catalog-search').dispatch('input');
assert.equal(node('#catalog-results').children[0].textContent, 'Não foram encontradas sugestões nesta coleção.');
assert.equal(node('#catalog-results').children[0].selector, 'p');
node('#catalog-search').value = 'The Holiday'; node('#catalog-search').dispatch('input');
assert.equal(node('#catalog-results').children.length, 1);
const holiday = evaluate("CURATED_CATALOG.christmas.find(movie => movie.title === 'The Holiday (2006)')");
evaluate('addCatalogMovie(CURATED_CATALOG.christmas.find(movie => movie.title === \'The Holiday (2006)\'))');
assert.equal(node('#count').textContent, 14, 'curated catalogue movie can be added to the wheel');
assert.equal(evaluate('movieIsAdded(CURATED_CATALOG.christmas.find(movie => movie.title === \'The Holiday (2006)\'))'), true, 'newly added suggestion changes to already added state');
assert.equal(evaluate('playlistRecords().at(-1).source'), 'curated', 'local movie keeps a manual curation source');
assert.equal(holiday.tmdbRating, null, 'local catalogue does not invent a TMDB rating');
node('#movies').value = 'Holiday A (2000)\nHoliday B (2001)'; node('#movies').dispatch('input');
node('#theme').value = 'halloween'; node('#theme').dispatch('change');
assert.equal(node('#count').textContent, 60);
assert.equal(node('#history-stats').textContent, '20 filmes diferentes · 27 sorteios');
node('#theme').value = 'christmas'; node('#theme').dispatch('change');
assert.equal(node('#movies').value, 'Holiday A (2000)\nHoliday B (2001)');
assert.equal(node('#history-stats').textContent, '0 filmes diferentes · 0 sorteios');
assert.equal(JSON.parse(storage.get('cinema-roulette-v5')).activeTheme, 'christmas', 'theme preference persists');
const restoredTheme = await createApp(Object.fromEntries([...storage].map(([key, raw]) => [key, JSON.parse(raw)])));
assert.equal(restoredTheme.node('#theme').value, 'christmas');
assert.equal(restoredTheme.node('#language').value, 'pt-PT');
assert.equal(restoredTheme.node('#movies').value, 'Holiday A (2000)\nHoliday B (2001)');

const migrated = await createApp({ 'halloween-movies-v1': 'Persisted One\nPersisted Two', 'halloween-history-v1': { 'Persisted One': 9 }, 'halloween-sound-v1': false });
assert.equal(migrated.node('#movies').value, 'Persisted One\nPersisted Two');
assert.equal(migrated.node('#history-stats').textContent, '1 filme diferente · 9 sorteios');
assert.equal(migrated.node('#sound').getAttribute('aria-pressed'), 'false');
assert.equal(migrated.storage.has('halloween-movies-v1'), true, 'legacy data remains as a recoverable backup');
const migratedAgain = await createApp(Object.fromEntries([...migrated.storage].map(([key, raw]) => [key, JSON.parse(raw)])));
assert.equal(migratedAgain.node('#history-stats').textContent, '1 filme diferente · 9 sorteios', 'repeated migration does not duplicate counts');
assert.equal(migratedAgain.node('#movies').value, 'Persisted One\nPersisted Two');
const migratedV2 = await createApp({ 'cinema-roulette-v2': { version: 2, activeTheme: 'halloween', language: 'pt-PT', soundEnabled: true, themes: { halloween: { movies: 'Old A (1990)\nOld B (1991)', history: { 'Old A (1990)': 3 } }, christmas: { movies: 'New Year Film (2000)', history: {} } } } });
assert.equal(migratedV2.node('#history-stats').textContent, '1 filme diferente · 3 sorteios');
assert.deepEqual(JSON.parse(migratedV2.storage.get('cinema-roulette-v5')).themes.halloween.playlist.map(movie => movie.id), ['manual:old a (1990)', 'manual:old b (1991)']);
assert.equal(migratedV2.storage.has('cinema-roulette-v2'), true, 'version 2 remains recoverable after migration');
const migratedV3 = await createApp({ 'cinema-roulette-v3': { version: 3, activeTheme: 'halloween', language: 'en', soundEnabled: true, themes: { halloween: { playlist: [{ id: 'manual:beetlejuice (1988)', title: 'Beetlejuice (1988)' }, { id: 'manual:unknown (2026)', title: 'Unknown (2026)' }], history: { 'manual:beetlejuice (1988)': { id: 'manual:beetlejuice (1988)', title: 'Beetlejuice (1988)', count: 7 } }, viewed: [], avoidViewed: false }, christmas: { playlist: [{ id: 'manual:klaus (2019)', title: 'Klaus (2019)' }], history: {}, viewed: [], avoidViewed: false } } } });
assert.equal(migratedV3.node('#history-stats').textContent, '1 unique movie · 7 draws');
