assert.equal(migratedV3.storage.has('cinema-roulette-v3'), true, 'v3 remains recoverable after successful migration');
const migratedV3Again = await createApp(Object.fromEntries([...migratedV3.storage].map(([key, raw]) => [key, JSON.parse(raw)])));
assert.equal(migratedV3Again.node('#history-stats').textContent, '1 unique movie · 7 draws', 'migration from v3 remains idempotent');
const migratedV4 = await createApp({ 'cinema-roulette-v4': { version: 4, activeTheme: 'halloween', language: 'pt-PT', soundEnabled: false, themes: { halloween: { playlist: [{ id: 'manual:a (2020)', title: 'A (2020)' }], history: { 'manual:a (2020)': { id: 'manual:a (2020)', title: 'A (2020)', count: 5 } }, viewed: ['manual:a (2020)'], avoidViewed: true, filters: { moods: ['scary'], maxDuration: 90 } }, christmas: { playlist: [{ id: 'manual:b (2021)', title: 'B (2021)' }], history: {}, viewed: [], avoidViewed: false, filters: { moods: [], maxDuration: null } } } } });
const upgradedV4 = JSON.parse(migratedV4.storage.get('cinema-roulette-v5'));
