const allowedOrigin = 'https://joaopef.github.io';
const requestToProxy = (path, { origin = allowedOrigin, method = 'GET', headers = {} } = {}) => new Request(`https://catalog.example/3/${path}`, { method, headers: { Origin: origin, ...headers } });
const unauthenticated = await tmdbProxy.fetch(requestToProxy('search/movie'), {});
assert.equal(unauthenticated.status, 503, 'missing TMDB credentials disable online mode safely');
const deniedOrigin = await tmdbProxy.fetch(requestToProxy('search/movie', { origin: 'https://attacker.example' }), { TMDB_API_READ_ACCESS_TOKEN: 'secret' });
assert.equal(deniedOrigin.status, 403, 'proxy rejects unknown browser origins');
const preflight = await tmdbProxy.fetch(requestToProxy('search/movie', { method: 'OPTIONS' }), {});
assert.equal(preflight.status, 204, 'proxy responds to browser preflight without credentials');
assert.equal(preflight.headers.get('Access-Control-Allow-Origin'), allowedOrigin);
const proxyNoQuery = await tmdbProxy.fetch(requestToProxy('search/movie'), { TMDB_API_READ_ACCESS_TOKEN: 'secret', RATE_LIMITER: {} });
assert.equal(proxyNoQuery.status, 400, 'proxy validates required search parameters');
const proxyDeniedRoute = await tmdbProxy.fetch(requestToProxy('configuration'), { TMDB_API_READ_ACCESS_TOKEN: 'secret', RATE_LIMITER: {} });
assert.equal(proxyDeniedRoute.status, 404, 'proxy only exposes the documented TMDB routes');
const passedRateLimiter = { idFromName: name => name, get: name => ({ async fetch() { assert.match(name, /^[a-f0-9]{64}$/); return new Response('OK'); } }) };
const originalFetch = globalThis.fetch;
let upstreamRequest;
try {
  globalThis.fetch = async (url, init) => { upstreamRequest = { url: new URL(url), init }; return new Response(JSON.stringify({ results: [] }), { headers: { 'Content-Type': 'application/json' } }); };
  const proxySearch = await tmdbProxy.fetch(requestToProxy('search/movie?query=The%20Thing&language=en-US&primary_release_year=1982', { headers: { 'CF-Connecting-IP': '203.0.113.10' } }), { TMDB_API_READ_ACCESS_TOKEN: 'secret-token-for-server', RATE_LIMITER: passedRateLimiter });
  assert.equal(proxySearch.status, 200);
  assert.equal(proxySearch.headers.get('Access-Control-Allow-Origin'), allowedOrigin);
  assert.equal(upstreamRequest.url.hostname, 'api.themoviedb.org');
  assert.equal(upstreamRequest.url.searchParams.get('query'), 'The Thing');
  assert.equal(upstreamRequest.url.searchParams.get('primary_release_year'), '1982');
  assert.equal(upstreamRequest.url.searchParams.has('api_key'), false);
  assert.equal(upstreamRequest.init.headers.Authorization, 'Bearer secret-token-for-server', 'server token is sent only from the Worker to TMDB');
  assert.equal(await proxySearch.text(), '{"results":[]}');
} finally { globalThis.fetch = originalFetch; }

const rows = new Map();
const limiterState = { storage: { async transaction(operation) { return operation({ get: async key => rows.get(key), put: async (key, value) => rows.set(key, value) }); } } };
const rateLimiter = new CinemaRateLimiter(limiterState);
for (let index = 0; index < 90; index++) assert.equal((await rateLimiter.fetch(new Request('https://rate-limit.internal/check', { method: 'POST' }))).status, 200);
const limited = await rateLimiter.fetch(new Request('https://rate-limit.internal/check', { method: 'POST' }));
assert.equal(limited.status, 429, 'atomic limiter rejects the 91st request in a minute');
assert.ok(Number(limited.headers.get('Retry-After')) > 0);
for (const count of [1, 2, 3, 9]) {
  const modeApp = await createApp();
  modeApp.setReduceMotion(true);
  modeApp.node('#movies').value = Array.from({ length: count }, (_, index) => index === 0 ? 'A very long title for a manually added movie with no poster' : `Film ${index}`).join('\n');
  modeApp.node('#movies').dispatch('input');
  modeApp.node('#draw-mode').value = 'doors'; modeApp.node('#draw-mode').dispatch('change');
  modeApp.node('#draw-pace').value = 'suspense'; modeApp.node('#draw-pace').dispatch('change');
  assert.equal(JSON.parse(modeApp.storage.get('cinema-roulette-v5')).themes.halloween.drawMode, 'doors', 'draw mode preference persists for Halloween');
  assert.equal(JSON.parse(modeApp.storage.get('cinema-roulette-v5')).themes.halloween.drawPace, 'suspense', 'draw pace preference persists for Halloween');
  const reloadedModeApp = await createApp({ 'cinema-roulette-v5': JSON.parse(modeApp.storage.get('cinema-roulette-v5')) });
  assert.equal(reloadedModeApp.node('#draw-mode').value, 'doors', 'draw mode survives a reload');
  assert.equal(reloadedModeApp.node('#draw-pace').value, 'suspense', 'draw pace survives a reload');
  modeApp.node('#spin').dispatch('click');
  const doors = modeApp.node('#doors').children;
  assert.equal(doors.length, Math.min(3, count), 'mystery doors only show available distinct movies');
  assert.equal(new Set(vm.runInContext('doorCandidates.map(movie => movie.id)', modeApp.sandbox)).size, Math.min(3, count), 'doors never repeat a movie in the same round');
  const historyBeforeDoors = JSON.stringify(vm.runInContext('history', modeApp.sandbox));
  assert.equal(JSON.stringify(vm.runInContext('history', modeApp.sandbox)), historyBeforeDoors, 'preparing mystery doors does not record a draw');
  const reveal = doors[0].dispatch('click');
  assert.equal(modeApp.audios[0].playCount, 0, 'doors never start the wheel sound');
  assert.equal(modeApp.audios.slice(2).reduce((total, audio) => total + audio.playCount, 0), 1, 'one creature effect starts on opening a door');
  modeApp.animationFrames.shift()(0);
  const picked = await reveal;
  assert.equal(modeApp.node('#result-title').textContent, picked.movie, 'door result card matches the drawn title');
  assert.ok(modeApp.node('#spin').innerHTML.includes('Escolher outra porta'));
  assert.equal(vm.runInContext('themeData.sessions.length', modeApp.sandbox), 1, 'opening a door records exactly one result');
  assert.equal(doors[0].getAttribute('aria-label').includes(picked.movie), true, 'the selected door reveals its title');
  assert.equal(doors[0].children.some(child => child.textContent === picked.movie), true, 'the selected door shows the movie title visually');
  assert.equal(modeApp.audios[1].playCount, 0, 'doors do not play the wheel completion ding');
  assert.equal(doors.slice(1).some(door => door.getAttribute('aria-label').includes(picked.movie)), false, 'other doors stay closed without revealing a title');
  assert.equal(vm.runInContext('themeData.sessions.at(-1).movies[0].id', modeApp.sandbox), picked.id, 'door result and session history use the same movie');
}
